/*
 * @brief: destroy page phone_book
 */
void destroy_page_phone_book(bk_lv_ui_t *bk_ui)
{
    if (bk_ui == NULL) {
        return;
    }
    
    if (bk_ui->phone_book != NULL) {
        lv_obj_del(bk_ui->phone_book);
        bk_ui->phone_book = NULL;
    }
}